def Q(prompt, opts, ci, whys, steps, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    """4-option multiple choice. `opts` lists the four option texts, `ci` is the index of the correct one,
    `whys` gives the reason for each wrong option, in the order they appear."""
    assert len(opts) == 4 and len(whys) == 3
    it = iter(whys)
    choices = [C(t, correct=True) if i == ci else C(t, why=next(it)) for i, t in enumerate(opts)]
    return MC(prompt, choices, steps=steps, concept=concept, skill=skill, hint=hint, feedback=feedback,
              diagram=diagram, diagram_alt=diagram_alt)


